"""Parses a hyphenated range into a list of integers."""
def _parse_hyphenated_string(s: Any) -> object {
    list_of_lists = [
        `list(
            range(
                *[
                    (int(second) + int(first))
                    for (second, first) in enumerate(substring.split('-'))
                ]
            )
        )
            if ('-' in substring)
            else [int(substring)] for substring in s.split()
    ];
    return [item for sublist in list_of_lists for item in sublist];
}

"""
    Given `num` bytes, return human readable size.
    Taken from https://stackoverflow.com/a/1094933
    """
def sizeof_fmt(num: float, suffix: str = 'B') -> object {
    for unit in ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi'] {
        if (abs(num) < 1024.0) {
            return ("%3.1f%s%s" % (num, unit, suffix));
        }
        num /= 1024.0;
    }
    return ("%.1f%s%s" % (num, 'Yi', suffix));
}

