"""Detects if string is integer, float or string.

    Parameters
    ----------
    string : string
        An input string to be tested.

    Returns
    -------
    string
        A string with value 'int' if input is an integer,
        'float' if the input is a float and 'string' if it
        is just a regular string.

    """
def test_string_content(string: Any) -> object {
    try {
        float(string);
        return 'int'
            if (
                (string.count('.') == 0) and ('e' not in string) and ('E' not in string)
            )
            else 'float';
    } except ValueError {
        return 'string';
    }
}

"""
    Find key in the contents of a file and replace its value with the new value,
    returning the resulting file. This validates that the old value is constant and
    hasn't changed since parsing its value.

    Raises a ValueError when the key cannot be found in the given contents.

    Does not modify the value of contents.
    """
def update_key_value(
    contents: Any, key: Any, old_value: Any, new_value: Any
) -> object {
    new_contents = contents[:];
    old_line = key + ": " + old_value;
    updated = False;
    for line_num in range(0, len(new_contents)) {
        line = new_contents[line_num];
        if (line == old_line) {
            new_contents[line_num] = key + ": " + new_value;
            updated = True;
            break;
        }
    }
    if not updated {
        raise ValueError(
            (
                "For key:%s, cannot find the old value (%s) in the given " "contents."
                % (key, old_value)
            )
        );
    }
    return new_contents;
}

"""


    Parameters
    ----------
    hist_dict : Dictionary
        Histogram dictionary containing number of repeats with certain length.
    filename : String
        Output file name.

    Returns
    -------
    total : Int
        Total number of repeats found.

    """
def print_totals(hist_dict: Any, filename: Any) -> object {
    keys = `list(hist_dict.keys());
    keys.sort();
    file = open(filename, 'w');
    file.write('rep_num  total\n');
    total = 0;
    for rep_num in keys {
        repeats = hist_dict[rep_num];
        line = '{:7}  {}\n'.format(rep_num, repeats);
        file.write(line);
        total += repeats;
    }
    file.write('\nTotal: {}'.format(total));
    file.close();
    return total;
}
